/// title : "Forms secure relationships with caregivers"
/// area : "Social & Emotional Development"
/// id : "e715b3e1-b6d3-4970-b731-a0428ff22d0c"
/// description : "Social & Emotional Development"
/// sortOrder : 1
/// createdAt : "2026-04-01T10:52:03.392Z"
/// updatedAt : "2026-04-01T10:52:03.392Z"

class Questions {
  Questions({
      String? title, 
      String? area, 
      String? id, 
      String? description, 
      num? sortOrder, 
      String? createdAt, 
      String? updatedAt,
      List<String>? optionCodes,
      List<QuestionAnswerOption>? answerOptions,}){
    _title = title;
    _area = area;
    _id = id;
    _description = description;
    _sortOrder = sortOrder;
    _createdAt = createdAt;
    _updatedAt = updatedAt;
    _answerOptions = answerOptions ?? const [];
    _optionCodes = optionCodes ??
        (_answerOptions.map((item) => item.code).toList());
}

  Questions.fromJson(dynamic json) {
    _title = json['title'];
    _area = json['area'];
    _id = json['id'];
    _description = json['description'];
    _sortOrder = json['sortOrder'];
    _createdAt = json['createdAt'];
    _updatedAt = json['updatedAt'];
    _answerOptions = _parseAnswerOptions(json);
    _optionCodes = _answerOptions.map((item) => item.code).toList();
  }
  String? _title;
  String? _area;
  String? _id;
  String? _description;
  num? _sortOrder;
  String? _createdAt;
  String? _updatedAt;
  List<String> _optionCodes = const [];
  List<QuestionAnswerOption> _answerOptions = const [];
Questions copyWith({  String? title,
  String? area,
  String? id,
  String? description,
  num? sortOrder,
  String? createdAt,
  String? updatedAt,
  List<String>? optionCodes,
  List<QuestionAnswerOption>? answerOptions,
}) => Questions(  title: title ?? _title,
  area: area ?? _area,
  id: id ?? _id,
  description: description ?? _description,
  sortOrder: sortOrder ?? _sortOrder,
  createdAt: createdAt ?? _createdAt,
  updatedAt: updatedAt ?? _updatedAt,
  optionCodes: optionCodes ?? _optionCodes,
  answerOptions: answerOptions ?? _answerOptions,
);
  String? get title => _title;
  String? get area => _area;
  String? get id => _id;
  String? get description => _description;
  num? get sortOrder => _sortOrder;
  String? get createdAt => _createdAt;
  String? get updatedAt => _updatedAt;
  List<QuestionAnswerOption> get answerOptions =>
      _answerOptions.isEmpty
          ? optionCodes
              .map((code) => QuestionAnswerOption(
                    code: code,
                    label: QuestionAnswerOption.defaultMeaning(code),
                  ))
              .toList()
          : _answerOptions;
  List<String> get optionCodes {
    if (_answerOptions.isNotEmpty) {
      return _answerOptions.map((item) => item.code).toList();
    }
    return _optionCodes.isEmpty ? const ['A', 'D', 'E'] : _optionCodes;
  }

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    map['title'] = _title;
    map['area'] = _area;
    map['id'] = _id;
    map['description'] = _description;
    map['sortOrder'] = _sortOrder;
    map['createdAt'] = _createdAt;
    map['updatedAt'] = _updatedAt;
    map['optionCodes'] = optionCodes;
    map['options'] = answerOptions.map((item) => item.toJson()).toList();
    return map;
  }

  static List<QuestionAnswerOption> _parseAnswerOptions(dynamic json) {
    const allowed = {'A', 'D', 'E'};
    final items = <QuestionAnswerOption>[];
    final seen = <String>{};

    void addOption(String code, String label) {
      if (!allowed.contains(code) || seen.contains(code)) return;
      seen.add(code);
      items.add(QuestionAnswerOption(
        code: code,
        label: label.trim().isEmpty
            ? QuestionAnswerOption.defaultMeaning(code)
            : label.trim(),
      ));
    }

    final fromOptions = json['options'];
    if (fromOptions is List) {
      for (final item in fromOptions) {
        if (item is Map) {
          addOption(
            item['code']?.toString().trim().toUpperCase() ?? '',
            (item['meaning'] ?? item['label'] ?? '').toString(),
          );
        }
      }
    }

    if (items.isEmpty) {
      final fromCodes = json['optionCodes'];
      if (fromCodes is List) {
        for (final item in fromCodes) {
          final code = item?.toString().trim().toUpperCase() ?? '';
          addOption(code, QuestionAnswerOption.defaultMeaning(code));
        }
      }
    }

    return items;
  }

}

class QuestionAnswerOption {
  const QuestionAnswerOption({
    required this.code,
    required this.label,
  });

  final String code;
  final String label;

  static String defaultMeaning(String code) {
    switch (code) {
      case 'A':
        return 'Doing it well';
      case 'D':
        return 'Learning it';
      case 'E':
        return 'Just starting';
      default:
        return code;
    }
  }

  Map<String, dynamic> toJson() => {
        'code': code,
        'label': label,
        'meaning': label,
      };
}